def shape(node):
    return ast.dump(node, include_attributes=False)
def expression(text):
    return ast.parse(text, mode='eval').body
replacements = {
    'PHASE_SCRIPTS + ["coupled73_codec.h"]': '[*PHASE_SCRIPTS, "coupled73_codec.h"]',
    'lines[:node.lineno - 1] + [f"{variable} = Path({json.dumps(replacement)})\\n"] + lines[node.end_lineno:]': '[*lines[:node.lineno - 1], f"{variable} = Path({json.dumps(replacement)})\\n", *lines[node.end_lineno:]]',
