    'print("REPLAY78 COMPLETE " + str(output / "results/replay78_comparison.json"), flush=True)': 'logging.info("REPLAY78 COMPLETE %s", output / "results/replay78_comparison.json")',
    'print("CONFIRM78 COMPLETE", json.dumps(summary), flush=True)': 'logging.info("CONFIRM78 COMPLETE %s", json.dumps(summary))',
}
replacements = {shape(expression(k)): (expression(v), k) for k,v in replacements.items()}
class AllowedChanges(ast.NodeTransformer):
    def __init__(self): self.counts = {}
    def visit(self, node):
        replacement = replacements.get(shape(node))
        if replacement:
            self.counts[replacement[1]] = self.counts.get(replacement[1],0) + 1
            return replacement[0]
        return super().visit(node)
def normalize_imports_and_logging(tree, raw_file):
    imports=[]
    body=[]
    for node in tree.body:
        if isinstance(node, ast.ImportFrom) and node.module == '__future__':
            assert [(n.name,n.asname) for n in node.names] == [('annotations',None)]
            assert not any(isinstance(n, ast.AnnAssign) or isinstance(n, ast.arg) and n.annotation is not None or isinstance(n, (ast.FunctionDef,ast.AsyncFunctionDef)) and n.returns is not None for n in ast.walk(tree))
            continue
        if isinstance(node, ast.Import) and [(n.name,n.asname) for n in node.names] in [[('logging',None)],[('re',None)]]:
            if node.names[0].name == 're':
                assert raw_file and not any(isinstance(n,ast.Name) and n.id=='re' for n in ast.walk(tree))
            continue
        if isinstance(node, ast.Expr) and shape(node.value)==shape(expression('logging.basicConfig(level=logging.INFO, format="%(message)s")')):
            assert not raw_file
            continue
        if isinstance(node,(ast.Import,ast.ImportFrom)):
            imports.append(node)
        else:
            body.append(node)
    tree.body=sorted(imports,key=shape)+body
    return tree
